import sys

class Node:
    __slots__ = ('val', 'next')
    def __init__(self, val):
        self.val = val
        self.next = None

class LinkedList:
    def __init__(self):
        self.dummy = Node(0)
        self.tail = self.dummy

    def append(self, x):
        node = Node(x)
        self.tail.next = node
        self.tail = node

    def dedupe(self):
        seen = set()
        prev = self.dummy
        cur = prev.next
        while cur:
            if cur.val in seen:
                prev.next = cur.next
            else:
                seen.add(cur.val)
                prev = cur
            cur = cur.next
        self.tail = prev

    def reverse(self, l, r):
        before = self.dummy
        for _ in range(l):
            before = before.next
        first = before.next
        prev, cur = None, first
        for _ in range(r - l + 1):
            nxt = cur.next
            cur.next = prev
            prev = cur
            cur = nxt
        before.next = prev
        first.next = cur
        if cur is None:
            self.tail = first

    def to_list(self):
        out = []
        cur = self.dummy.next
        while cur:
            out.append(cur.val)
            cur = cur.next
        return out

def main():
    lines = sys.stdin.read().split('\n')
    q = int(lines[0])
    lst = LinkedList()
    out = []
    for i in range(1, q + 1):
        p = lines[i].split()
        if p[0] == 'append':
            lst.append(int(p[1]))
        elif p[0] == 'dedupe':
            lst.dedupe()
        elif p[0] == 'reverse':
            lst.reverse(int(p[1]), int(p[2]))
        else:
            vals = lst.to_list()
            out.append(' '.join(map(str, vals)) if vals else 'EMPTY')
    print('\n'.join(out))

