    def sim(nops, vals, weights, maxprints=50, prefill=0):
        ops = []
        size = 0
        prints = 0
        for _ in range(prefill):
            ops.append('append %d' % rng.choice(vals))
            size += 1
        while len(ops) < nops:
            kind = rng.choices(['append', 'dedupe', 'reverse', 'print'], weights)[0]
            if kind == 'print' and prints >= maxprints:
                kind = 'append'
            if kind == 'reverse' and size == 0:
                kind = 'append'
            if kind == 'append':
                ops.append('append %d' % rng.choice(vals))
                size += 1
            elif kind == 'dedupe':
                ops.append('dedupe')
                # size shrinks by an unknown amount; track via exact simulation below
            elif kind == 'reverse':
                l = rng.randint(0, size - 1)
                r = rng.randint(l, size - 1)
                ops.append('reverse %d %d' % (l, r))
            else:
                ops.append('print')
                prints += 1
            if kind == 'dedupe':
                # recompute size exactly
                cur = []
                for o in ops:
                    p = o.split()
                    if p[0] == 'append':
                        cur.append(int(p[1]))
                    elif p[0] == 'dedupe':
                        seen = set()
                        nxt = []
                        for v in cur:
                            if v not in seen:
                                seen.add(v)
                                nxt.append(v)
                        cur = nxt
                    elif p[0] == 'reverse':
                        l, r = int(p[1]), int(p[2])
                        cur[l:r + 1] = cur[l:r + 1][::-1]
                size = len(cur)
        return '%d\n%s' % (len(ops), '\n'.join(ops))
    tests = [
        '1\nprint',
        '3\nappend 4\nprint\nreverse 0 0',
        '5\nappend 1\nappend 1\nappend 1\ndedupe\nprint',
