import java.io.*;

public class Main {
    static class LinkedList {
        LinkedList() {
            // Write your solution here
        }

        void append(long x) {}

        void dedupe() {}

        void reverse(int l, int r) {}

        List<Long> toList() {
            return new ArrayList<>();
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int q = Integer.parseInt(br.readLine().trim());
        LinkedList lst = new LinkedList();
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < q; i++) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            String op = st.nextToken();
            if (op.equals("append")) {
                lst.append(Long.parseLong(st.nextToken()));
            } else if (op.equals("dedupe")) {
                lst.dedupe();
            } else if (op.equals("reverse")) {
                int l = Integer.parseInt(st.nextToken());
                int r = Integer.parseInt(st.nextToken());
                lst.reverse(l, r);
            } else {
                List<Long> v = lst.toList();
                if (v.isEmpty()) sb.append("EMPTY");
                else for (int j = 0; j < v.size(); j++) sb.append(v.get(j)).append(j + 1 < v.size() ? " " : "");
                sb.append('\n');
            }
        }
        System.out.print(sb);
    }
}
